mapper.select:
SELECT task_no,business_no,state,attempt_count,claim_version,lease_owner,lease_until,retry_cycle_started_at created_at
FROM process_task
WHERE task_no=#{taskNo}

mapper.update:
UPDATE process_task
SET state='SUCCEEDED',lease_owner=NULL,lease_until=NULL,last_error=NULL,version=version+1
WHERE task_no=#{taskNo} AND state='RUNNING' AND lease_owner=#{leaseOwner} AND claim_version=#{claimVersion}

UPDATE process_task
SET state='READY',lease_owner=NULL,lease_until=NULL,next_retry_at=TIMESTAMPADD(SECOND,#{retryDelaySeconds},UTC_TIMESTAMP(3)),last_error=#{lastError},version=version+1
WHERE task_no=#{taskNo} AND state='RUNNING' AND lease_owner=#{leaseOwner} AND claim_version=#{claimVersion}
